using UnityEngine; namespace MyLumo { public class ThirdPersonLumoCamera:MonoBehaviour { public Transform target; public Vector3 offset=new(0,3.2f,-6.5f); public float followSpeed=6,lookHeight=1.6f; void LateUpdate(){if(!target)return;var d=target.TransformPoint(offset);transform.position=Vector3.Lerp(transform.position,d,1-Mathf.Exp(-followSpeed*Time.deltaTime));var look=target.position+Vector3.up*lookHeight;transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(look-transform.position),1-Mathf.Exp(-followSpeed*Time.deltaTime));} } }
